import pytest
import click
from click.testing import CliRunner


def test_deprecated_option_warns(runner: CliRunner) -> None:
    @click.command()
    @click.option("--count", default=1, help="Number of greetings.", deprecated=True)
    @click.option("--name", prompt="Your name", help="The person to greet.")
    def hello(count, name):
        """Simple program that greets NAME for a total of COUNT times."""
        for x in range(count):
            click.echo(f"Hello {name}!")

    result = runner.invoke(hello, ["--count", "2", "--name", "Test"], input="Test\n")
    assert "Deprecated: Option '--count' is deprecated." in result.output

import os
import pytest
import click
from click.testing import CliRunner
import warnings

@pytest.fixture
def runner():
    return CliRunner()

def test_file_option_resource_warning_on_completion(runner):
    config_file_path = "test_config.txt"

    @click.group()
    @click.option(
        "--config_file",
        default=config_file_path,
        type=click.File(mode="r"),
        help="help",
    )
    def cli(config_file):
        pass

    # Create a dummy config file
    with open(config_file_path, "w") as f:
        f.write("test content")

    try:
        # Simulate shell completion
        env = {
            "SHELL_COMPLETION_VAR": "bash_complete",
            "_CLICK_CLI_COMPLETE": "bash_complete",
            "COMP_WORDS": "cli --config_file",
            "COMP_CWORD": "1",
        }

        with warnings.catch_warnings(record=True) as w:
            warnings.simplefilter("always")
            result = runner.invoke(cli, ["--config_file"], env=env, complete_var="SHELL_COMPLETION_VAR")

            # Assert that no ResourceWarning related to unclosed files is issued
            for warning_message in w:
                if issubclass(warning_message.category, ResourceWarning) and "unclosed file" in str(warning_message.message):
                    pytest.fail(f"ResourceWarning: {warning_message.message}")

            # Ensure the completion command itself didn't fail unexpectedly
            assert result.exit_code == 0

    finally:
        # Clean up the dummy config file
        if os.path.exists(config_file_path):
            os.remove(config_file_path)

import pytest
from jinja2 import Environment
from jinja2 import UndefinedError
from jinja2 import DictLoader

def test_issue_1253_elif_undefined_error(env):
    template_string = """
    {% if new_data_set_created is defined %}
        {% if new_data_set_created == True %}
            The new image data set <strong>{{ form_data["data_set_name"] }}</strong> has been created.
            {% set form_data = {"data_set_name": "", "client": "", "project": ""} %}
        {% else %}
            The new image data set <strong>{{ form_data["data_set_name"] }}</strong> could not be created.<br />
        {% endif %}
    {% elif deleted_data_set is defined %}
        The image data set <strong>{{ deleted_data_set }}</strong> has been deleted from DB and from disk.
        {% set form_data = {"data_set_name": "", "client": "", "project": ""} %}
    {% else %}
        {% set form_data = {"data_set_name": "", "client": "", "project": ""} %}
    {% endif %}
    """
    template = env.from_string(template_string)

    # This call should not raise an UndefinedError for form_data
    # when new_data_set_created is True, even with the elif block present.
    # The bug causes it to raise UndefinedError because the `form_data`
    # set in the outer scope is not correctly propagated into the inner `if` block
    # when an `elif` is present.
    rendered_output = template.render(
        new_data_set_created=True,
        form_data={"data_set_name": "test_dataset", "client": "test_client", "project": "test_project"}
    )

    assert "The new image data set <strong>test_dataset</strong> has been created." in rendered_output

import pytest
from jinja2 import Environment
from jinja2 import TemplateSyntaxError


def test_namespace_multi_variable_assignment(env):
    template = """
        {% set full = namespace(id="", prev_id="") -%}
        {% for id in endpoints recursive %}
          {% set full.prev_id, full.id = full.id, full.id + "/" + id -%}
        {% endfor -%}
        {{ full.id }}
    """
    env = Environment()
    tmpl = env.from_string(template)
    # The bug causes a TemplateSyntaxError during parsing.
    # If the bug is fixed, this render call should succeed.
    assert tmpl.render(endpoints=["a", "b"]) == "/a/b"

import pytest
from jinja2 import Environment
from jinja2 import DictLoader
from jinja2.ext import InternationalizationExtension


class TestI18nBlockPGettext:
    def test_block_pgettext_syntax(self):
        env = Environment(
            extensions=[InternationalizationExtension],
            loader=DictLoader(
                {
                    "test.html": """
                        {% pgettext "context" %}Hello{% endpgettext %}
                    """
                }
            ),
        )
        # The bug is that the parser does not recognize `pgettext` as a block.
        # This test asserts that the template can be parsed without syntax errors.
        # We don't care about the rendering result here, just that it parses.
        env.get_template("test.html")
        assert True # If we reach here, parsing succeeded, and the bug is fixed.

import unittest

from sqlglot import parse_one
from sqlglot.errors import ParseError


class TestReprobot5178(unittest.TestCase):
    def test_trino_cte_udf_parse_error(self):
        sql = """
        WITH FUNCTION f(num int)
            RETURNS int
            RETURN num
        SELECT f(1);
        """
        try:
            parse_one(sql, dialect="trino")
            self.assertTrue(True)  # If no ParseError, test passes
        except ParseError as e:
            self.fail(f"Parsing the CTE UDF raised a ParseError: {e}")
